<?php

declare(strict_types=1);

namespace AndyDefer\PhpVo\Enums;

/**
 * Distance units enum.
 *
 * Only length units relevant for geographic distance computation are listed.
 *
 * @author Generated by Andy Defer
 */
enum DistanceUnit: string
{
    case METRE = 'm';
    case KILOMETRE = 'km';
    case CENTIMETRE = 'cm';
    case MILLIMETRE = 'mm';
    case MICROMETRE = 'µm';
    case NANOMETRE = 'nm';

    /**
     * Conversion factor to the base unit (metre).
     */
    public function toMetres(): float
    {
        return match ($this) {
            self::METRE => 1.0,
            self::KILOMETRE => 1000.0,
            self::CENTIMETRE => 0.01,
            self::MILLIMETRE => 0.001,
            self::MICROMETRE => 1e-6,
            self::NANOMETRE => 1e-9,
        };
    }

    /**
     * Convert a value expressed in this unit to another unit.
     */
    public function convertTo(float $value, self $target): float
    {
        if ($this === $target) {
            return $value;
        }

        return $value * $this->toMetres() / $target->toMetres();
    }
}
